import{_ as e,o as t,c as r,a2 as d}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"维护开发者文档","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/guides/documentation","contentType":"guide","prev":false,"next":{"text":"发布教程站点","link":"/getting-started/publish-docs"}},"headers":[],"relativePath":"guides/documentation.md","filePath":"guides/documentation.md"}'),o={name:"guides/documentation.md"};function s(n,a,i,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="维护开发者文档" tabindex="-1">维护开发者文档 <a class="header-anchor" href="#维护开发者文档" aria-label="Permalink to &quot;维护开发者文档&quot;">​</a></h1><p>文档随公开能力一起交付：实现自己的 SaaS 功能时，同时更新使用该接口的教程、代码示例、双语说明和验证入口。</p><h2 id="选择正确的页面" tabindex="-1">选择正确的页面 <a class="header-anchor" href="#选择正确的页面" aria-label="Permalink to &quot;选择正确的页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>开始写什么</th><th>完成检查</th></tr></thead><tbody><tr><td>教程</td><td>前章代码状态、本章新增变更与结果</td><td>同一份业务代码可以继续下一章</td></tr><tr><td>任务指南</td><td>当前开发目标、前提、公开接口与最小实现</td><td>独立进入也能完成任务</td></tr><tr><td>概念</td><td>定义、真实关系图和最小代码</td><td>能理解何时使用、为何存在和边界</td></tr><tr><td>参考</td><td>事实来源、分类、参数、返回与限制</td><td>能定位当前准确合同</td></tr></tbody></table><p>后端教程以文件、代码、请求和结果为主。每步明确执行目录、依赖、完整变更和预期响应；复杂实现先给最小可运行路径，再解释关键细节。</p><h2 id="登记双语页面" tabindex="-1">登记双语页面 <a class="header-anchor" href="#登记双语页面" aria-label="Permalink to &quot;登记双语页面&quot;">​</a></h2><p>Markdown 是唯一可编辑正文来源。在中文文件旁创建同名 <code>.en.md</code>，在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/site.json" target="_blank" rel="noreferrer">site.json</a> 登记稳定 id、两组标题、源文件、发布路由、分组和页面 type。</p><p>教程序列使用 <code>previous</code> / <code>next</code> 的章节 id。没有明确关系时关闭自动相邻页，避免把下一章送到不相关的指南。</p><p>旧发布路径保持稳定；源文件可以移动，链接和站点声明一起更新。生成站点根据当前语言解析目标，页脚链接到构建使用的提交。</p><h2 id="让代码保持可运行" tabindex="-1">让代码保持可运行 <a class="header-anchor" href="#让代码保持可运行" aria-label="Permalink to &quot;让代码保持可运行&quot;">​</a></h2><p>使用 <code>&lt;&lt;&lt;</code> 引用受检查的源码。示例应明确插入位置，并在同一验证入口编译或执行；片段链接到完整实现。API DTO 来自 Rust/OpenAPI，配置默认值来自 Settings/FIELDS。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>对应业务的 HTTP 或公开能力检查验证成功、拒绝和关键失败。浏览器验证阅读与导航；这些证据各有责任，构建成功不能代替教学跟做。</p><h2 id="示例内容的所有权" tabindex="-1">示例内容的所有权 <a class="header-anchor" href="#示例内容的所有权" aria-label="Permalink to &quot;示例内容的所有权&quot;">​</a></h2><p>专有教程与代码登记在示例清单；共享页面中的示例链接放入已登记 marker。移除参考业务时，相关内容和导航一起移除，Core 文档仍应可构建。</p><h2 id="维护者资料" tabindex="-1">维护者资料 <a class="header-anchor" href="#维护者资料" aria-label="Permalink to &quot;维护者资料&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>保存术语，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/ARCHITECTURE.md" target="_blank" rel="noreferrer">架构规则</a>说明依赖与运行合同，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/adr/0002-executable-removable-reference.md" target="_blank" rel="noreferrer">ADR</a>记录决定。<a href="./../architecture/v1-coverage">能力覆盖与历史验收</a>提供实现证据，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/agents/development-flow.md" target="_blank" rel="noreferrer">开发流程</a>与<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/agents/documentation.md" target="_blank" rel="noreferrer">作者规则</a>说明维护责任；GitHub Issues 是当前实施状态的来源。</p><p>需要发布自己的站点时，按<a href="./../getting-started/publish-docs">发布文档</a>操作。</p><hr><p>源码版本：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/guides/maintain-docs.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,20)])])}const u=e(o,[["render",s]]);export{b as __pageData,u as default};
